            "药盒上的 etiket（标签） 写明用法；bijsluiter（说明书） 提供详细信息。",
            "部分药物如 paracetamol 可以 zonder recept（无处方） 购买。",
            "药物要按说明保存，远离儿童；旧药可交回药房。"
