      "color": "#138a45",
      "summary": "本章讲育儿和教育。孩子年龄阶段：`baby` 0-1 岁，`peuter` 1-4 岁，`kleuter` 4-6 岁，`schoolkind` 6-12 岁，`puber` 12-18 岁。",
      "explanation": [
        "本章讲育儿和教育。孩子年龄阶段：`baby` 0-1 岁，`peuter` 1-4 岁，`kleuter` 4-6 岁，`schoolkind` 6-12 岁，`puber` 12-18 岁。",
        "怀孕后由助产士（`verloskundige`）检查和指导。顺利时可在家或医院生产；有问题找妇科医生（`gynaecoloog`）。产后可安排 `kraamhulp` 在家帮忙。母亲有产假（`zwangerschapsverlof`），具体政策可能需要核对最新信息。",
        "0-4 岁孩子去 `consultatiebureau` 做成长检查、听力视力、营养睡眠建议、疫苗（`vaccinaties`）。父母工作时可用 `oppas`、`kinderdagverblijf`、`buitenschoolse opvang`。费用高，但可申请 `kinderopvangtoeslag`。所有孩子都有 `kinderbijslag`。",
        "荷兰教育有 `vrijheid van onderwijs`，父母可选学校。5-16 岁有义务教育（`leerplicht`），16-17 岁如果还没有足够文凭也要继续上学。孩子不能随便为假期请假，否则可能罚款。",
        "学前有 `peuterspeelzaal` 和 `voorschool`。小学 `basisschool` 从 4 岁左右开始，组别是 groep 1 到 8；group 8 后根据建议和测试去中学。中学分 `VMBO`、`HAVO`、`VWO`，分别通向 MBO、HBO、大学等路径。"
      ],
