      "title": "De geschiedenis van Nederland",
      "zhTitle": "荷兰历史",
      "color": "#2f6f8f",
      "summary": "荷兰历史从罗马人、低地国家、中世纪开始。中世纪多数人是农民，城市卫生差，寿命短。1568-1648 是八十年战争（`Tachtigjarige Oorlog`），荷兰反抗西班牙统治和宗教压迫。Willem van Oranje 是重要政治领袖，主张宗教自由，1584 年被杀；橙色因此成为荷兰象征之一。",
      "explanation": [
        "荷兰历史从罗马人、低地国家、中世纪开始。中世纪多数人是农民，城市卫生差，寿命短。1568-1648 是八十年战争（`Tachtigjarige Oorlog`），荷兰反抗西班牙统治和宗教压迫。Willem van Oranje 是重要政治领袖，主张宗教自由，1584 年被杀；橙色因此成为荷兰象征之一。",
        "1588 年荷兰成为共和国，1648 年正式独立。17 世纪是黄金时代（`Gouden Eeuw`），荷兰因海上贸易、VOC、亚洲非洲美洲贸易致富，也涉及奴隶贸易。阿姆斯特丹运河房、艺术如 Rembrandt 的《夜巡》与这一时期有关。",
        "1814 年荷兰成为王国，1815 年有宪法，1848 年之后民主制度更强。比利时 1830 年成为独立国家。19 世纪工业化后，工厂劳动条件差，后来出现政党、投票权扩大、禁止童工、义务教育。1917 年所有男性获得投票权，1919 年女性获得投票权。",
        "第一次世界大战荷兰没有参战。第二次世界大战中德国 1940 年占领荷兰，Rotterdam 被轰炸，犹太人被迫害、 deportatie 到集中营。Anne Frank 在 Amsterdam 的 Achterhuis 躲藏并写日记。1945 年 5 月 5 日荷兰解放；每年 5 月 4 日 Dodenherdenking，5 月 5 日 Bevrijdingsdag。",
        "战后荷兰重建，建立社会保障，如 AOW。1953 年大洪水后修建 Deltaplan。1970 年代经济好，土耳其和摩洛哥的客工（`gastarbeiders`）来荷兰工作。后来移民规则变严格，2007 年有 Wet Inburgering。"
      ],
